@r2.c1 w.request.constraint request=$r2 on=attribute attribute=node.x value="next to the last" words="next to the last box" operator=eq phase=result

@f1 w.request.filler text="leave the other boxes alone"
@r1 w.request.request act=undo mood=do words="bring back the box from step 2" predicate="bring back"
@r1.t w.request.target request=$r1 family=node mode=new family_words=box fill=journal_step determiner=indefinite
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=step.index value=2 words="the box from step 2" operator=eq phase=selector
@r2 w.request.request act=change mood=do words="and swap it with the one to its left" predicate=swap
@r2.t w.request.target request=$r2 family=node mode=existing determiner=definite fill=context
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
