@r1 w.request.request act=undo mood=do predicate=undo
@r1.t w.request.target request=$r1 family=node mode=new determiner=indefinite
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=node.shape value=square operator=eq phase=result

@f1 w.request.filler text=then
